package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public final class StudyActivity extends PocketActivity {
 static JSONArray cards(Context c)throws Exception{JSONObject s=PocketStore.read(c,"study");return s.optJSONArray("cards")==null?new JSONArray():s.getJSONArray("cards");}
 static synchronized void save(Context c,JSONArray cards)throws Exception{PocketStore.write(c,"study",new JSONObject().put("cards",cards));}
 static synchronized void add(Context c,String front,String back)throws Exception{if(front.trim().isEmpty()||back.trim().isEmpty()||front.length()>4096||back.length()>4096)throw new IOException("Invalid card");JSONArray all=cards(c);if(all.length()>=5000)throw new IOException("Maximum 5000 cards");all.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("front",front.trim()).put("back",back.trim()).put("due",0).put("days",0));save(c,all);}
 static synchronized void grade(Context c,String id,int grade)throws Exception{JSONArray latest=cards(c);for(int n=0;n<latest.length();n++){JSONObject row=latest.getJSONObject(n);if(id.equals(row.optString("id"))){int days=nextDays(row.optInt("days"),grade);row.put("days",days).put("due",System.currentTimeMillis()+(days==0?600000L:days*86400000L));save(c,latest);return;}}}
 static synchronized void delete(Context c,String id)throws Exception{JSONArray latest=cards(c),next=new JSONArray();for(int n=0;n<latest.length();n++)if(!id.equals(latest.getJSONObject(n).optString("id")))next.put(latest.get(n));save(c,next);}
 static int nextDays(int previous,int grade){return grade==0?0:grade==1?1:Math.min(365,Math.max(1,previous)*(grade==2?2:3));}
 protected void render()throws Exception{JSONArray all=cards(this);int due=0;for(int n=0;n<all.length();n++)if(all.getJSONObject(n).optLong("due")<=System.currentTimeMillis())due++;list(L.t("Carduri de învățare"),Arrays.asList(L.t("Începe repetarea")+" · "+due,L.t("Card nou"),L.t("Toate cardurile")+" · "+all.length(),L.t("Importă CSV / TSV"),L.t("Exportă CSV")),0,new Choice(){public void pick(int at){if(at==0)review();else if(at==1)edit(L.t("Card nou"),new String[]{L.t("Întrebare"),L.t("Răspuns")},new String[]{"",""},new Saved(){public void save(String[] v)throws Exception{add(StudyActivity.this,v[0],v[1]);home();}},goHome());else if(at==2)all();else if(at==3)chooseFile("csv|tsv|txt",1);else export();}},"",null);}
 private void review(){try{final JSONArray all=cards(this);for(int n=0;n<all.length();n++){final JSONObject card=all.getJSONObject(n);if(card.optLong("due")>System.currentTimeMillis())continue;page(L.t("Întrebare"),card.getString("front"),goHome(),L.t("Arată răspunsul"),new Runnable(){public void run(){page(card.optString("front"),card.optString("back"),goHome(),L.t("Evaluează"),new Runnable(){public void run(){options(L.t("Cât de ușor a fost?"),new String[]{L.t("Din nou · 10 minute"),L.t("Greu · 1 zi"),L.t("Bine"),L.t("Ușor")},new Choice(){public void pick(int grade){try{StudyActivity.grade(StudyActivity.this,card.getString("id"),grade);review();}catch(Exception e){problem(e);}}});}});}});return;}page(L.t("Repetare completă"),L.t("Nu mai sunt carduri scadente acum."),goHome(),"",null);}catch(Exception e){problem(e);}}
 private void all(){try{final JSONArray rows=cards(this);ArrayList<String> labels=new ArrayList<>();for(int n=0;n<rows.length();n++)labels.add(rows.getJSONObject(n).optString("front")+"\n"+new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(rows.getJSONObject(n).optLong("due"))));list(L.t("Toate cardurile"),labels,0,new Choice(){public void pick(final int at){try{page(rows.getJSONObject(at).optString("front"),rows.getJSONObject(at).optString("back"),goHome(),L.t("Șterge"),new Runnable(){public void run(){remove(L.t("Ștergi cardul?"),new Runnable(){public void run(){try{StudyActivity.delete(StudyActivity.this,rows.getJSONObject(at).getString("id"));all();}catch(Exception e){problem(e);}}});}});}catch(Exception e){problem(e);}}},"",null);back=goHome();}catch(Exception e){problem(e);}}
 protected void selectedFile(int request,final File file){final ArrayList<String[]> imported=new ArrayList<>();job(L.t("Import în curs"),new Work(){public void run()throws Exception{imported.addAll(PocketTable.parse(PocketStore.fileBytes(file,2*1024*1024),5000));if(cards(StudyActivity.this).length()+imported.size()>5000)throw new IOException("Maximum 5000 cards");}},new Runnable(){public void run(){options(L.t("Adaugi cardurile importate?"),new String[]{L.t("Anulează"),L.t("Importă")+" · "+imported.size()},new Choice(){public void pick(int yes){if(yes==1)job(L.t("Import în curs"),new Work(){public void run()throws Exception{synchronized(StudyActivity.class){JSONArray rows=cards(StudyActivity.this);if(rows.length()+imported.size()>5000)throw new IOException("Maximum 5000 cards");for(String[] row:imported)rows.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("front",row[0]).put("back",row[1]).put("due",0).put("days",0));save(StudyActivity.this,rows);}}},goHome());else home();}});}});}
 private File last;private void export(){job(L.t("Export carduri"),new Work(){public void run()throws Exception{StringBuilder s=new StringBuilder();JSONArray rows=cards(StudyActivity.this);for(int n=0;n<rows.length();n++)s.append(PocketStore.csv(rows.getJSONObject(n).getString("front"))).append(',').append(PocketStore.csv(rows.getJSONObject(n).getString("back"))).append('\n');last=PocketStore.output(StudyActivity.this,"Study","cards.csv");BackupEngine.write(last,s.toString().getBytes("UTF-8"));}},new Runnable(){public void run(){exported(last);}});}
}
